+void ScreenBrightnessControl::setContrast(const QString &displayName, int value)
+{
+    const QModelIndex index = m_displays.displayIndex(displayName);
+    if (m_displays.data(index, ScreenBrightnessDisplayModel::ContrastRole) == value) {
+        return;
+    }
+
+    QDBusMessage msg = QDBusMessage::createMethodCall(SCREENBRIGHTNESS_SERVICE,
+                                                      SCREENBRIGHTNESS_DISPLAY_PATH_TEMPLATE.arg(displayName),
+                                                      SCREENBRIGHTNESS_DISPLAY_IFACE,
+                                                      u"SetContrast"_s);
+    msg << value;
+    QDBusConnection::sessionBus().asyncCall(msg);
+
+    m_displays.onContrastChanged(displayName, m_displays.data(index, ScreenBrightnessDisplayModel::MaxContrastRole).toInt(), value);
+}
