+DisplayBrightness *ScreenBrightnessController::contrastDisplay(const QString &displayId) const
+{
+    const auto it = m_displaysById.find(displayId);
+    if (it == m_displaysById.end() || it->second.zombie || !it->second.display->usesDdcCi()) {
+        return nullptr;
+    }
+    // KWin controls DDC/CI monitors through the brightness devices we hand over to it,
+    // find the one it uses for this display the same way it does
+    const std::optional<QByteArray> &edid = it->second.match.edidData;
+    if (!edid.has_value() || edid->isEmpty()) {
+        return nullptr;
+    }
+    for (DisplayBrightness *display : m_externalDisplays) {
+        if (!display || !display->usesDdcCi() || display->maxContrast() <= 0) {
+            continue;
+        }
+        if (const std::optional<QByteArray> edidBeginning = display->edidData();
+            edidBeginning.has_value() && !edidBeginning->isEmpty() && edid->startsWith(*edidBeginning)) {
+            return display;
+        }
+    }
+    return nullptr;
+}
+
+int ScreenBrightnessController::maxContrast(const QString &displayId) const
+{
+    const DisplayBrightness *display = contrastDisplay(displayId);
+    return display ? display->maxContrast() : 0;
+}
+
+int ScreenBrightnessController::contrast(const QString &displayId) const
+{
+    const DisplayBrightness *display = contrastDisplay(displayId);
+    return display ? display->contrast() : 0;
+}
+
+void ScreenBrightnessController::setContrast(const QString &displayId, int value)
+{
+    DisplayBrightness *display = contrastDisplay(displayId);
+    if (!display) {
+        qCWarning(POWERDEVIL) << "Set screen contrast failed: no contrast control for display with id" << displayId;
+        return;
+    }
+    const int boundedValue = std::clamp(value, 0, display->maxContrast());
+    qCDebug(POWERDEVIL) << "Set screen contrast of" << displayId << "to" << boundedValue << "/" << display->maxContrast();
+
+    if (display->contrast() != boundedValue) {
+        display->setContrast(boundedValue);
+        Q_EMIT contrastChanged(displayId, display->maxContrast(), boundedValue);
+    }
+}
+
+void ScreenBrightnessController::updateContrastSupport(const QString &displayId)
+{
+    if (auto it = m_displaysById.find(displayId); it != m_displaysById.end()) {
+        if (const int max = maxContrast(displayId); it->second.maxContrast != max) {
+            it->second.maxContrast = max;
+            Q_EMIT contrastChanged(displayId, max, contrast(displayId));
+        }
+    }
+}
+
+void ScreenBrightnessController::onDisplayUsesDdcCiChanged(DisplayBrightness *display)
+{
+    const auto it = std::ranges::find_if(m_displaysById, [display](const std::pair<QString, DisplayInfo> &pair) {
+        return pair.second.display == display;
+    });
+    if (it != m_displaysById.end()) {
+        updateContrastSupport(it->first);
+    }
+}
